<script>
(() => {
const container=document.getElementById('fee-heads');
const add=document.getElementById('add-fee-head');
let index=1;
add.addEventListener('click',()=>{
const row=document.createElement('div'); row.className='tg-card fee-head-row'; row.style.padding='14px';
const fields=[['Fee head','name','text'],['Code','code','text'],['Amount (₹)','amount','number'],['Category','category','text']];
const grid=document.createElement('div'); grid.className='tg-form';
fields.forEach(([label,key,type])=>{const wrap=document.createElement('div');wrap.className='tg-field';const caption=document.createElement('label');caption.textContent=label;const input=document.createElement('input');input.name='heads['+index+']['+key+']';input.type=type;input.required=key!=='category';if(type==='number'){input.min='0';input.step='0.01';}wrap.append(caption,input);grid.append(wrap);});
row.append(grid);container.append(row);index++;
});
})();
</script>
